15	/// A class to analyze APK and AOT snapshot and generate a breakdown of the data.
16	class SizeAnalyzer {
17	  SizeAnalyzer({
18	    @required this.fileSystem,
19	    @required this.logger,
20	    this.appFilenamePattern = 'libapp.so',
21	  });
22	
23	  final FileSystem fileSystem;
24	  final Logger logger;
25	  final Pattern appFilenamePattern;
26	  String _appFilename;
27	
28	  static const String aotSnapshotFileName = 'aot-snapshot.json';
29	
30	  static const int tableWidth = 80;
31	
32	  static const int _kAotSizeMaxDepth = 2;
33	  static const int _kZipSizeMaxDepth = 1;
34	
35	  /// Analyze the [aotSnapshot] in an uncompressed output directory.
36	  Future<Map<String, dynamic>> analyzeAotSnapshot({
37	    @required Directory outputDirectory,
38	    @required File aotSnapshot,
39	    @required File precompilerTrace,
40	    @required String type,
41	    String excludePath,
42	  }) async {
43	    logger.printStatus('▒' * tableWidth);
44	    logger.printStatus('━' * tableWidth);
45	    final _SymbolNode aotAnalysisJson = _parseDirectory(
46	      outputDirectory,
47	      outputDirectory.parent.path,
48	      excludePath,
49	    );
50	
51	    // Convert an AOT snapshot file into a map.
52	    final Map<String, dynamic> processedAotSnapshotJson = treemapFromJson(
53	      json.decode(aotSnapshot.readAsStringSync()),
54	    );
55	    final _SymbolNode aotSnapshotJsonRoot = _parseAotSnapshot(processedAotSnapshotJson);
56	
57	    for (final _SymbolNode firstLevelPath in aotAnalysisJson.children) {
58	      _printEntitySize(
59	        firstLevelPath.name,
60	        byteSize: firstLevelPath.byteSize,
61	        level: 1,
62	      );
63	      // Print the expansion of lib directory to show more info for `appFilename`.
64	      if (firstLevelPath.name == fileSystem.path.basename(outputDirectory.path)) {
65	        _printLibChildrenPaths(firstLevelPath, '', aotSnapshotJsonRoot, _kAotSizeMaxDepth, 0);
66	      }
67	    }
68	
69	    logger.printStatus('▒' * tableWidth);
70	
71	    Map<String, dynamic> apkAnalysisJson = aotAnalysisJson.toJson();
72	
73	    apkAnalysisJson['type'] = type; // one of apk, aab, ios, macos, windows, or linux.
74	
75	    apkAnalysisJson = _addAotSnapshotDataToAnalysis(
76	      apkAnalysisJson: apkAnalysisJson,
77	      path: _locatedAotFilePath,
78	      aotSnapshotJson: processedAotSnapshotJson,
79	      precompilerTrace: json.decode(precompilerTrace.readAsStringSync()) as Map<String, Object>,
80	    );
81	
82	    assert(_appFilename != null);
83	    return apkAnalysisJson;
84	  }
