86	  /// Analyzes [apk] and [aotSnapshot] to output a [Map] object that includes
87	  /// the breakdown of the both files, where the breakdown of [aotSnapshot] is placed
88	  /// under 'lib/arm64-v8a/$_appFilename'.
89	  ///
90	  /// [kind] must be one of 'apk' or 'aab'.
91	  /// The [aotSnapshot] can be either instruction sizes snapshot or a v8 snapshot.
92	  Future<Map<String, dynamic>> analyzeZipSizeAndAotSnapshot({
93	    @required File zipFile,
94	    @required File aotSnapshot,
95	    @required File precompilerTrace,
96	    @required String kind,
97	  }) async {
98	    assert(kind == 'apk' || kind == 'aab');
99	    logger.printStatus('▒' * tableWidth);
100	    _printEntitySize(
101	      '${zipFile.basename} (total compressed)',
102	      byteSize: zipFile.lengthSync(),
103	      level: 0,
104	      showColor: false,
105	    );
106	    logger.printStatus('━' * tableWidth);
107	
108	    final _SymbolNode apkAnalysisRoot = _parseUnzipFile(zipFile);
109	
110	    // Convert an AOT snapshot file into a map.
111	    final Map<String, dynamic> processedAotSnapshotJson = treemapFromJson(
112	      json.decode(aotSnapshot.readAsStringSync()),
113	    );
114	    final _SymbolNode aotSnapshotJsonRoot = _parseAotSnapshot(processedAotSnapshotJson);
115	    for (final _SymbolNode firstLevelPath in apkAnalysisRoot.children) {
116	      _printLibChildrenPaths(firstLevelPath, '', aotSnapshotJsonRoot, _kZipSizeMaxDepth, 0);
117	    }
118	    logger.printStatus('▒' * tableWidth);
119	
120	    Map<String, dynamic> apkAnalysisJson = apkAnalysisRoot.toJson();
121	
122	    apkAnalysisJson['type'] = kind;
123	
124	    assert(_appFilename != null);
125	    apkAnalysisJson = _addAotSnapshotDataToAnalysis(
126	      apkAnalysisJson: apkAnalysisJson,
127	      path: _locatedAotFilePath,
128	      aotSnapshotJson: processedAotSnapshotJson,
129	      precompilerTrace: json.decode(precompilerTrace.readAsStringSync()) as Map<String, Object>,
130	    );
131	
132	    return apkAnalysisJson;
133	  }
134	
135	  _SymbolNode _parseUnzipFile(File zipFile) {
136	    final Archive archive = ZipDecoder().decodeBytes(zipFile.readAsBytesSync());
137	    final Map<List<String>, int> pathsToSize = <List<String>, int>{};
138	
139	    for (final ArchiveFile archiveFile in archive.files) {
140	      pathsToSize[fileSystem.path.split(archiveFile.name)] = archiveFile.rawContent.length;
141	    }
142	    return _buildSymbolTree(pathsToSize);
143	  }
144	
145	  _SymbolNode _parseDirectory(Directory directory, String relativeTo, String excludePath) {
146	    final Map<List<String>, int> pathsToSize = <List<String>, int>{};
147	    for (final File file in directory.listSync(recursive: true).whereType<File>()) {
148	      if (excludePath != null && file.uri.pathSegments.contains(excludePath)) {
149	        continue;
150	      }
151	      final List<String> path = fileSystem.path.split(
152	        fileSystem.path.relative(file.path, from: relativeTo));
153	      pathsToSize[path] = file.lengthSync();
154	    }
155	    return _buildSymbolTree(pathsToSize);
156	  }
157	
158	  List<String> _locatedAotFilePath;
159	
160	  List<String> _buildNodeName(_SymbolNode start, _SymbolNode parent) {
161	    final List<String> results = <String>[start.name];
162	    while (parent != null && parent.name != 'Root') {
163	      results.insert(0, parent.name);
164	      parent = parent.parent;
165	    }
166	    return results;
167	  }
168	
169	  _SymbolNode _buildSymbolTree(Map<List<String>, int> pathsToSize) {
170	     final _SymbolNode rootNode = _SymbolNode('Root');
171	    _SymbolNode currentNode = rootNode;
172	
173	    for (final List<String> paths in pathsToSize.keys) {
174	      for (final String path in paths) {
175	        _SymbolNode childWithPathAsName = currentNode.childByName(path);
176	
177	        if (childWithPathAsName == null) {
178	          childWithPathAsName = _SymbolNode(path);
179	          if (matchesPattern(path, pattern: appFilenamePattern) != null) {
180	            _appFilename = path;
181	            childWithPathAsName.name += ' (Dart AOT)';
182	            _locatedAotFilePath = _buildNodeName(childWithPathAsName, currentNode);
183	          } else if (path == 'libflutter.so') {
184	            childWithPathAsName.name += ' (Flutter Engine)';
185	          }
186	          currentNode.addChild(childWithPathAsName);
187	        }
188	        childWithPathAsName.addSize(pathsToSize[paths]);
189	        currentNode = childWithPathAsName;
190	      }
191	      currentNode = rootNode;
192	    }
193	    return rootNode;
194	  }
